import JSZip from "jszip";
import { isValidSiteSpec } from "./schema";
import { TOP_DIRECTORY_SUBMISSIONS } from "./directories";

function esc(value) {
	return JSON.stringify(value ?? "");
}

function buildGeneratedPreset(spec) {
	const categories = spec.taxonomy.categories;
	return `import { buildCategoryMeta } from "./shared";

const categories = ${JSON.stringify(categories, null, "\t")};

/** Generated by ToolDir SiteSpec planner — do not hand-edit blindly */
export const generatedPreset = {
	id: ${esc(spec.template)},
	landingTemplate: ${esc(spec.template)},
	brand: ${esc(spec.brand.name)},
	tagline: ${esc(spec.brand.tagline)},
	theme: { accent: ${esc(spec.brand.accent)} },
	entitySingular: ${esc(spec.taxonomy.entitySingular)},
	entityPlural: ${esc(spec.taxonomy.entityPlural)},
	seoTitle: ${esc(spec.seo.title)},
	seoDescription: ${esc(spec.seo.description)},
	categories,
	categoryMeta: buildCategoryMeta(categories),
	seed: ${JSON.stringify(spec.seedListings, null, "\t")},
	landing: {
		badge: ${esc(spec.landing.badge)},
		headlineBefore: ${esc(spec.landing.headlineBefore)},
		headlineAccent: ${esc(spec.landing.headlineAccent)},
		subhead: ${esc(spec.landing.subhead)},
		primaryCta: ${esc(spec.landing.primaryCta)},
		secondaryCta: ${esc(spec.landing.secondaryCta)},
		trendingTitle: ${esc(spec.landing.trendingTitle)},
		trendingSubhead: ${esc(spec.landing.trendingSubhead)},
		statsTitle: "Built for this niche",
		statsSubhead: ${esc(spec.brand.description)},
		testimonialsTitle: "Early supporters",
		testimonialsSubhead: "Founders exploring this directory",
		pricingSubhead: "Book a launch slot for homepage placement.",
		submitCardTitle: ${esc(spec.landing.primaryCta)},
		submitCardBody: ${esc(spec.brand.description)},
		footerBlurb: ${esc(spec.brand.description)},
		navSubmitLabel: ${esc(spec.landing.primaryCta)},
	},
	stats: {
		monthlyVisitors: "10K+",
		itemsSubmitted: "${Math.max(spec.seedListings.length, 12)}+",
		itemsSubmittedLabel: "${spec.taxonomy.entityPlural[0].toUpperCase()}${spec.taxonomy.entityPlural.slice(1)} listed",
		thirdStat: "${spec.taxonomy.categories.length}",
		thirdStatLabel: "Categories",
	},
};
`;
}

function buildMarketingMd(spec) {
	const dirs = TOP_DIRECTORY_SUBMISSIONS.map(
		(d) => `- [${d.name}](${d.url}) — ${d.focus}`
	).join("\n");
	const channels = (spec.marketing.channels || [])
		.map((c) => `- ${c}`)
		.join("\n");

	return `# Marketing plan — ${spec.brand.name}

## Positioning
${spec.marketing.positioning}

## Channels
${channels || "- Launch on X and Indie Hackers"}

## Submit to these directories (top 20)
${dirs}

## Notes
- Lead with the niche pain, not the template.
- Offer free listings early to seed SEO pages.
- Ask each listed product for a backlink / badge.
`;
}

function buildSeoMd(spec) {
	const blogs = (spec.seo.blogIdeas || [])
		.map(
			(b, i) => `### ${i + 1}. ${b.title}
Keyword: \`${b.keyword}\`
Outline:
${(b.outline || []).map((o) => `- ${o}`).join("\n")}`
		)
		.join("\n\n");

	return `# SEO pack — ${spec.brand.name}

## Title
${spec.seo.title}

## Meta description
${spec.seo.description}

## Keywords
${(spec.seo.keywords || []).join(", ")}

## Blog ideas
${blogs}
`;
}

function buildGenerationMd(spec) {
	return `# Generated project — ${spec.brand.name}

Mode: **${spec.mode}**
Base template: **${spec.template}**

This ZIP overlays a ToolDir niche pack with AI-planned **content & config only**.
Application components stay known-good (no free-form AI JSX).

## Quick start
1. \`npm install\`
2. Copy \`.env.example\` → \`.env.local\` and fill Supabase / Stripe
3. Run \`supabase-migrations.sql\` in Supabase SQL editor
4. \`npm run dev\`

## Files written by the generator
- \`directory.config.js\` — locked niche
- \`lib/presets/generated-overlay.js\` — brand, categories, seed listings
- \`GENERATION.md\` — this file
- \`CURSOR_PROMPT.md\` — paste into Cursor to continue
- \`MARKETING.md\` — launch channels + directories
- \`SEO_IDEAS.md\` — blog / keyword ideas

## Cursor next steps
See \`CURSOR_PROMPT.md\`.
`;
}

/**
 * Build a lightweight "starter overlay" ZIP from SiteSpec.
 * Includes config + docs. For full app code, buyers still use Gumroad / pack-zip niches.
 * When baseZipBuffer is provided, merges overlay into that archive.
 */
export async function createGeneratorZip(spec, { baseZipBuffer } = {}) {
	if (!isValidSiteSpec(spec)) {
		throw new Error("Invalid SiteSpec");
	}

	const zip = baseZipBuffer
		? await JSZip.loadAsync(baseZipBuffer)
		: new JSZip();

	const slug = spec.brand.name
		.toLowerCase()
		.replace(/[^a-z0-9]+/g, "-")
		.replace(/^-|-$/g, "");

	zip.file(
		"directory.config.js",
		`/** Locked by ToolDir generator for ${spec.brand.name} */
export const DIRECTORY_CONFIG = {
	preset: ${JSON.stringify(spec.template)},
};
`
	);

	zip.file("lib/presets/generated-overlay.js", buildGeneratedPreset(spec));
	zip.file(
		"lib/generator/last-sitespec.json",
		JSON.stringify(spec, null, 2)
	);
	zip.file("GENERATION.md", buildGenerationMd(spec));
	zip.file("CURSOR_PROMPT.md", `${spec.cursorPrompt}\n`);
	zip.file("MARKETING.md", buildMarketingMd(spec));
	zip.file("SEO_IDEAS.md", buildSeoMd(spec));
	zip.file(
		".env.generator.example",
		`# Generated niche hint
NEXT_PUBLIC_DIRECTORY_PRESET=${spec.template}
# NEXT_PUBLIC_PRESET_SWITCHER=
`
	);

	if (!baseZipBuffer) {
		zip.file(
			"README.md",
			`# ${spec.brand.name}

${spec.brand.description}

This package is a **ToolDir generator overlay** (${spec.mode}).

If you already purchased the full ToolDir boilerplate, merge these files into that repo:
1. Copy \`lib/presets/generated-overlay.js\`
2. Wire it in \`lib/presets/index.js\` (or replace your locked niche preset content)
3. Set \`directory.config.js\` preset to \`${spec.template}\`
4. Follow \`GENERATION.md\`, \`MARKETING.md\`, and \`SEO_IDEAS.md\`

Download the full boilerplate: https://shreyvijayvargiya.gumroad.com/l/nextjs-supabase-directory-boilerplate
`
		);
	}

	const buffer = await zip.generateAsync({
		type: "nodebuffer",
		compression: "DEFLATE",
		compressionOptions: { level: 6 },
	});

	return {
		buffer,
		filename: `${slug || "tooldir"}-${spec.mode}-starter.zip`,
	};
}
